def handle(app, svc):
    resp = svc.apply(app)
    # API v2: {"api_version": 2, "result": {"outcome": ..., "credit_limit": int}}
    # Fall back to v1 shape {"decision": ..., "limit": int} for safety.
    if "result" in resp:
        result = resp["result"]
        outcome = result.get("outcome")
        limit = int(result.get("credit_limit", 0) or 0)
    else:
        outcome = resp.get("decision")
        limit = int(resp.get("limit", 0) or 0)

    if outcome in ("approve", "approved"):
        if app.get("employment") == "self_employed" and int(app.get("requested_limit", 0) or 0) > 6000:
            return {"action": "queue_review", "limit": 0}
        return {"action": "issue", "limit": limit}
    if outcome in ("decline", "declined"):
        return {"action": "decline", "limit": 0}
    # refer / manual_review
    return {"action": "queue_review", "limit": 0}

